import fs from 'node:fs/promises';import{createHash}from'node:crypto';import{RemoteD1Database}from'../runner/report2-d1-adapter.mjs';import{loadDailyUsageAggregate,evaluateDailyReservationBudget,evaluateWithinRunReservation,reserveRunBudget,finalizeRunUsage}from'../runner/d1-preaction-budget-guard.mjs';import{APPROVED_HTX_SCOPE,APPROVED_HTX_ANALYSIS_CONTRACTS}from'../current-generation/files/src/approved-htx-analysis-scope.mjs';
const db=new RemoteD1Database(process.env.REPORT2_D1_BRIDGE_URL,process.env.REPORT2_D1_BRIDGE_TOKEN),now=Date.now(),reservation={rows_read:500,rows_written:50},id='HTX_SCOPE_COLLECTOR_READBACK:'+process.env.GITHUB_RUN_ID,actor='HUB_PUBLIC_COLLECTOR',generation='MY_REPORT_2_CURRENT_20260928_CANONICAL_RUNTIME_V12_CONTRACT_INTEGRITY_20M',out={schema:'HTX_CURRENT_APPROVED_COLLECTOR_ORIGINAL_READBACK_V1',run:Number(process.env.GITHUB_RUN_ID),head:process.env.GITHUB_SHA,read_ts:now,sourceHTTP:0,MAIN:0,Telegram:0,source_clocks_refreshed:false,approved_assets:APPROVED_HTX_SCOPE.approved_assets,forced_collector_run:false,read_only_market_history:true};let admitted=false;
try{
 out.daily_admission=evaluateDailyReservationBudget({daily:await loadDailyUsageAggregate(db,now),nextReservation:reservation,maxDailyReads:3500000,maxDailyWrites:70000});if(!out.daily_admission.allowed)throw Error('D1_DAILY_ADMISSION_DENIED');await reserveRunBudget(db,{reservationId:id,now,reservation});admitted=true;
 const latest=await db.prepare('SELECT bucket FROM report2_market_snapshot_batch_v1 WHERE actor=?1 AND generation=?2 ORDER BY bucket DESC LIMIT 1').bind(actor,generation).first();if(!latest)throw Error('NO_ORIGINAL_COLLECTOR_BUCKET');
 if(!evaluateWithinRunReservation({reservation,currentUsage:db.usageSnapshot(),extraRowsRead:32,extraRowsWritten:4}).allowed)throw Error('D1_READBACK_HEADROOM_DENIED');
 const records=(await db.prepare('SELECT shard,status,payload_hash,payload,source_timestamps_json,received_ts FROM report2_market_snapshot_batch_v1 WHERE actor=?1 AND generation=?2 AND bucket=?3 ORDER BY shard ASC LIMIT 32').bind(actor,generation,latest.bucket).all()).results;
 if(!records.length)throw Error('NO_ORIGINAL_SHARDS');const meta=JSON.parse(records[0].source_timestamps_json),rows=[];if(meta.expected_shards!==records.length)throw Error('INCOMPLETE_ORIGINAL_SHARDS');
 for(let i=0;i<records.length;i++){const r=records[i];if(r.shard!==i||r.status!=='COMPLETE'||createHash('sha256').update(r.payload).digest('hex')!==r.payload_hash)throw Error('ORIGINAL_SHARD_INTEGRITY');rows.push(...JSON.parse(r.payload));}
 if(rows.length!==meta.universe_total)throw Error('ORIGINAL_UNIVERSE_COUNT');const counts=new Map();for(const r of rows)counts.set(r.contract,(counts.get(r.contract)||0)+1);const by=new Map(rows.map(r=>[r.contract,r]));
 out.original_bucket=latest.bucket;out.original_catalog_source_ts=meta.contracts;out.original_market_source_ts=meta.market;out.original_received_ts=records[0].received_ts;out.original_shards=records.length;out.original_all_derivatives_count=rows.length;out.original_shard_hashes=records.map(r=>({shard:r.shard,payload_sha256:r.payload_hash}));
 out.approved_rows=APPROVED_HTX_ANALYSIS_CONTRACTS.map(c=>{const r=by.get(c.contract_code);return{contract:c.contract_code,status:!r?'MISSING':counts.get(c.contract_code)!==1?'DUPLICATE':r.source_status,source_ts:r?.observed_ts??null,price:r?.price??null,oi_contracts:r?.oi_contracts??null,oi_value_usdt:r?.oi_value_usdt??null,funding_rate:r?.funding_rate??null,missing:r?.missing??null,fresh_at_read:!!r&&Number.isFinite(r.price)&&r.price>0&&Number.isSafeInteger(r.observed_ts)&&r.observed_ts<=now&&now-r.observed_ts<=300000};});
 out.approved_present=out.approved_rows.filter(r=>!['MISSING','DUPLICATE'].includes(r.status)).length;out.approved_current_closed=out.approved_rows.filter(r=>r.status==='CLOSED'&&r.fresh_at_read).length;out.new_assets=out.approved_rows.filter(r=>['CT-USDT','RLC-USDT'].includes(r.contract));out.no_noncrypto_in_approved_rows=true;out.collection_covers_all_approved=out.approved_present===APPROVED_HTX_SCOPE.approved_assets;out.status=out.collection_covers_all_approved?'ALL_APPROVED_ASSETS_PRESENT_IN_ORIGINAL_NATURAL_COLLECTOR_BUCKET':'ORIGINAL_COLLECTOR_HAS_EXPLICIT_APPROVED_GAPS';out.full_240min_flow_coverage_claimed=false;out.new_fresh_SENT=false;
}catch(e){out.status='ORIGINAL_COLLECTOR_READBACK_NOT_CLOSED';out.reason=e.message;}
finally{if(admitted)out.finalized_usage=await finalizeRunUsage(db,{reservationId:id,sourceRunId:process.env.GITHUB_RUN_ID,usage:db.usageSnapshot()});out.D1=db.usageSnapshot();if(out.D1.unknown_ops||out.D1.rows_read>reservation.rows_read||out.D1.rows_written>reservation.rows_written){out.status='D1_READBACK_ENVELOPE_NOT_CLOSED';out.reason='D1_READBACK_ENVELOPE_NOT_CLOSED';}await fs.mkdir('audit-output/htx-scope-verification',{recursive:true});await fs.writeFile('audit-output/htx-scope-verification/original-collector-readback.json',JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify({...out,approved_rows:undefined}));if(out.D1.unknown_ops)process.exitCode=1;}
